clc; clear; close all;
%%%%%%%%%%%%%%%%%%%%% Constant Pararmeters %%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Vehicle
m  = 500;          % kg
L  = 4.0;          % m
D  = 0.40;         % m
S  = pi*D^2/4;     % m^2

%% Inertia
Ix = 250;          % kg m^2
Iy = 800;          % kg m^2
Iz = 800;          % kg m^2

I = diag([Ix Iy Iz]);

%% Propulsion
T = 28000;         % N

%% TVC
delta_max = deg2rad(8);
tau_TVC   = 0.05; % sec

%% CG / thrust location
xCG = 2.0;         % m from nose
rT  = [-1.8; 0; 0]; % m, relative to CG

%% Environment
g   = 9.80665;     % m/s^2
rho = 1.225;       % kg/m^3

%% Reference quantities
Aref = S;

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%% Simulation %%%%%%%%%%%%%%%%%%%%%%%%%%%

%Taking the No of Iteration as Input - Iteration/100 = Time of Simulation
N = input("Enter the Number of Iteration: ");
K = input("Enter the Navigation Constant (Generally 3-5): ");

% Initializing the Target Position
rt = NaN(3,N+1);

% Initializing the Missile's Position
rm = NaN(3,N+1);

% Target Trajectory
rt(:,1) = [30000; 20000; 9000];%m --- Initial Position
Vt = 500*rt(:,1)/vecnorm(rt(:,1));%[-240; -120; 10] 
at = [5; 3; 5];  %m/s^2

%Distance Between the Missile and Target
R = NaN(3,N+1);
Time = NaN(1,N+1);

%%Assuming missile has reached this position and Velocity
r0 = rt(:,1)/vecnorm(rt(:,1));
rm(:,1) = [0;0;0];
Vm = 1200*r0;%m/s - Missile
Acc_max = (T/m)*sin(delta_max);%Because we have to take max lateral Acceleration

%%Initial Orientation of the Missile
Angle = NaN(3,N+1);
Angle(:,1) = [0;0;0];
Quat = Angle2quat(Angle(:,1));
p = 0; q = 0; r = 0;%Angular rates in body frame

dt = 0.01;
Time(1) = 0;
fprintf("Initial Distance between the Target and Missile is: %.2f\n",vecnorm(rm(:,1) - rt(:,1))); %[output:894d2a76]

for i = 1:N %[output:group:989e4eef]

    V_rel = Vt - Vm;
    Vm_mag = vecnorm(Vm);
    Vm_hat = Vm/Vm_mag;
    R(:,i) = rt(:,i) - rm(:,i);
    Omega_LOS = cross(R(:,i),V_rel)/norm(R(:,i))^2;

    New = Inertial2Body(R(:,i),Quat);
    aNGLE = acosd(dot(New,[1,0,0])/vecnorm(New));
    fprintf("Angle is: %f\n ", aNGLE); %[output:3df6d64c]
    
    %Latex Command
    Acc_cmd = K*Vm_mag*cross(Omega_LOS,Vm_hat);
    Acc_mag = vecnorm(Acc_cmd);

    if Acc_mag > Acc_max
        Acc_cmd = Acc_cmd * Acc_max/Acc_mag;
    end
    Body_Acc = Inertial2Body(Acc_cmd,Quat);%Converting the latex into the Body frame
    Body_Vel = Inertial2Body(Vm,Quat);

    F_Req = m*Body_Acc;%Assuming No gravity and Aerodynamic Forces

    DeltaY = atan2(F_Req(2),sqrt(F_Req(1)^2 + F_Req(3)^2));%);
    DeltaZ = atan2(F_Req(3),sqrt(F_Req(1)^2 + F_Req(2)^2));%TVC Deflection direction

    % Apply TVC actuator limits 
    DeltaY = max(-delta_max, min(delta_max, DeltaY));
    DeltaZ = max(-delta_max, min(delta_max, DeltaZ));

    F_TVC = T*[cos(DeltaY)*cos(DeltaZ);
               sin(DeltaY)*cos(DeltaZ);
               sin(DeltaZ)];

    %Applying Translational Dynamics 
    U_dot = (F_TVC(1)/m) - q*Body_Vel(3) + r*Body_Vel(2);
    V_dot = (F_TVC(2)/m) - r*Body_Vel(1) + p*Body_Vel(3);
    W_dot = (F_TVC(3)/m) - p*Body_Vel(2) + q*Body_Vel(1);

    Body_Vel = Body_Vel + [U_dot; V_dot; W_dot]*dt;

    % Calculate missile's velocity components
    Vm = Body2Inertial(Body_Vel,Quat);     

    %Updating missile's position
    rm(:,i+1) = rm(:,i) + Vm*dt + Acc_cmd*(dt^2/2);
   

    %Applying Rotational Dynamics
    Moment = cross(rT,F_TVC);

    p_dot = (Moment(1) - (Iz - Iy)*q*r)/Ix;
    q_dot = (Moment(2) - (Ix - Iz)*r*p)/Iy;
    r_dot = (Moment(3) - (Iy - Ix)*p*q)/Iz;

    p = p + p_dot*dt;
    q = q + q_dot*dt;
    r = r + r_dot*dt;

    %Attitude Update
    Omega = [0 -p -q -r;
             p  0  r -q;
             q  -r 0  p;
             r  q  -p  0];
    
    Quat_dot = (0.5)*Omega*Quat;
    Quat = Quat + Quat_dot*dt;
    Quat = Quat/vecnorm(Quat);
    Angle(:,i+1) = quat2Angle(Quat);

    %Updating Target position
    rt(:,i+1) = rt(:,i) + Vt*dt + 0.5*at*dt^2;
    
    %Updating Target Velocity
    Vt = Vt + at*dt;

    Time(i+1) = Time(i) + dt;
    R(:,i+1) = rt(:,i+1) - rm(:,i+1);
    
    if (norm(R(:,i+1)) < 50)
        break;
    end

end %[output:group:989e4eef]

if (min(vecnorm(R)) > 50) %[output:group:10338373]
    fprintf("The Target accelerated and got out of reach!\n"); %[output:70fd0110]
end %[output:group:10338373]

if (min(vecnorm(R)) <= 50)
   fprintf("Mission Succesfull! Target Eliminated\n");
end

%Plotting the Target Trajectory

plot3(rt(1,:),rt(2,:),rt(3,:),marker = "o", Color = "r"); %[output:0c6c73e7]
title("Target's Trajectory") %[output:0c6c73e7]
xlabel("X Coordinate"); %[output:0c6c73e7]
ylabel("Y Coordinate"); %[output:0c6c73e7]
zlabel("Z Coordinate"); %[output:0c6c73e7]
hold on; %[output:0c6c73e7]
grid on; %[output:0c6c73e7]

plot3(rm(1,:),rm(2,:),rm(3,:),marker = "*", Color = "g"); %[output:0c6c73e7]
title("Missile's Trajectory") %[output:0c6c73e7]
xlabel("X Coordinate"); %[output:0c6c73e7]
ylabel("Y Coordinate"); %[output:0c6c73e7]
zlabel("Z Coordinate"); %[output:0c6c73e7]

figure; %[output:5748ec53]
plot(Time,vecnorm(R, 2, 1).',marker = "+", Color = "b"); %[output:5748ec53]
title("Reletive distance between the Missile and Interceptor!"); %[output:5748ec53]
xlabel("Time in seconds"); %[output:5748ec53]
ylabel("Distance b/w the Target and Missile"); %[output:5748ec53]
grid on; %[output:5748ec53]

plot (Time, Angle) %[output:98354626]
title("Orientation of the Missile with Time"); %[output:98354626]
xlabel("Time"); %[output:98354626]
ylabel("Orientation"); %[output:98354626]
legend("Phi","Theta","Psi"); %[output:98354626]
grid on; %[output:98354626]

fprintf("Time taken to reach closest distance of %.2f m to the Target is: %.2f seconds\n",min(vecnorm(R)),Time(i+1)); %[output:6f1bcf38]

fprintf("Final Distance between the Target and Missile is: %.2f\n",norm(R(:,i))); %[output:3f588772]

fprintf("Minimum Distance between the Target and Missile is: %.2f\n",min(vecnorm(R))); %[output:7a64f780]

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%% Required Functions %%%%%%%%%%%%%%%%%%%%%%%%%%%%

function Angle = quat2Angle(q)
    qn = norm(q);
    q0 = q(1)/qn; q1 = q(2)/qn; q2 = q(3)/qn; q3 = q(4)/qn;
    
    phi   = atan2(2 * (q0 * q1 + q2 * q3), q0 * q0 + q3 * q3 - q1 * q1 - q2 * q2);
    theta  = asin (2 * (q0 * q2 - q1 * q3));
    shi    = atan2(2 * (q0 * q3 + q1 * q2), q0 * q0 + q1 * q1 - q2 * q2 - q3 * q3);
    
    Angle = [phi; theta; shi];
end

function q = Angle2quat(Angle)
    phi = Angle(1); theta = Angle(2); shi = Angle(3);

    cphi = cos(phi/2);   sphi = sin(phi/2);
    cth  = cos(theta/2); sth  = sin(theta/2);
    cshi = cos(shi/2);   sshi = sin(shi/2);
    
    q1 = cphi*cth*cshi + sphi*sth*sshi;   % q0 
    q2 = sphi*cth*cshi - cphi*sth*sshi;   % q1
    q3 = cphi*sth*cshi + sphi*cth*sshi;   % q2
    q4 = cphi*cth*sshi - sphi*sth*cshi;   % q3
    
    q = [q1; q2; q3; q4];
    q = q / norm(q);   % unit magnitude

end

function V_B = Inertial2Body(V_I,Quat)
    Angle = quat2Angle(Quat);
    phi = Angle(1);
    theta = Angle(2);
    psi = Angle(3);

    C_B_N = [cos(theta)*cos(psi), cos(theta)*sin(psi), -sin(theta);
    
             sin(phi)*sin(theta)*cos(psi) - cos(phi)*sin(psi), ...
             sin(phi)*sin(theta)*sin(psi) + cos(phi)*cos(psi), ...
             sin(phi)*cos(theta);
    
             cos(phi)*sin(theta)*cos(psi) + sin(phi)*sin(psi), ...
             cos(phi)*sin(theta)*sin(psi) - sin(phi)*cos(psi), ...
             cos(phi)*cos(theta)];
    
    V_B = C_B_N*V_I;

end

function V_I = Body2Inertial(V_B,Quat)
    Angle = quat2Angle(Quat);
    phi = Angle(1);
    theta = Angle(2);
    psi = Angle(3);

    C_N_B = [cos(theta)*cos(psi), ...
             sin(phi)*sin(theta)*cos(psi) - cos(phi)*sin(psi), ...
             cos(phi)*sin(theta)*cos(psi) + sin(phi)*sin(psi);
    
             cos(theta)*sin(psi), ...
             sin(phi)*sin(theta)*sin(psi) + cos(phi)*cos(psi), ...
             cos(phi)*sin(theta)*sin(psi) - sin(phi)*cos(psi);
    
             -sin(theta), ...
             sin(phi)*cos(theta), ...
             cos(phi)*cos(theta)];
    
    V_I = C_N_B*V_B;

end

